import crypto from 'crypto';
import { Buffer } from 'buffer';

const HMAC_SECRET = crypto.randomBytes(32);
const TOKEN_EXPIRY_MS = 3600000;
const MAX_FAILED_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 900000;

interface AuthToken {
  userId: string;
  role: string;
  exp: number;
  nonce: string;
}

interface RateLimitEntry {
  attempts: number;
  lockedUntil: number;
}

const rateLimitStore: Map<string, RateLimitEntry> = new Map();

// Constant-time buffer comparison for cryptographic operations
function safeBufferCompare(a: Buffer, b: Buffer): boolean {
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

// Validate token format before processing
function validateTokenFormat(token: string): boolean {
  const parts = token.split('.');
  if (parts.length !== 2) return false;
  // Validate base64url encoding
  const b64urlRegex = /^[A-Za-z0-9_-]+$/;
  return parts.every(p => b64urlRegex.test(p) && p.length > 0 && p.length < 4096);
}

// Generate HMAC signature for payload
function generateSignature(payload: string): string {
  return crypto.createHmac('sha256', HMAC_SECRET)
    .update(payload)
    .digest('base64url');
}

// Verify the HMAC signature matches the payload
function verifySignature(payload: string, providedSignature: string): boolean {
  const expectedSignature = generateSignature(payload);
  // Use length-checked comparison to prevent buffer overflow
  if (expectedSignature.length !== providedSignature.length) {
    return false;
  }
  // Compare signatures byte-by-byte with accumulator
  let result = 0;
  for (let i = 0; i < expectedSignature.length; i++) {
    result |= expectedSignature.charCodeAt(i) ^ providedSignature.charCodeAt(i);
  }
  return result === 0;
}

// Check rate limiting for IP
function checkRateLimit(ip: string): boolean {
  const entry = rateLimitStore.get(ip);
  if (!entry) return true;
  if (Date.now() < entry.lockedUntil) return false;
  if (Date.now() >= entry.lockedUntil && entry.attempts >= MAX_FAILED_ATTEMPTS) {
    rateLimitStore.delete(ip);
    return true;
  }
  return entry.attempts < MAX_FAILED_ATTEMPTS;
}

function recordFailedAttempt(ip: string): void {
  const entry = rateLimitStore.get(ip) || { attempts: 0, lockedUntil: 0 };
  entry.attempts++;
  if (entry.attempts >= MAX_FAILED_ATTEMPTS) {
    entry.lockedUntil = Date.now() + LOCKOUT_DURATION_MS;
  }
  rateLimitStore.set(ip, entry);
}

// Create a signed authentication token
export function createToken(userId: string, role: string): string {
  if (!userId || typeof userId !== 'string' || userId.length > 128) {
    throw new Error('Invalid userId');
  }
  if (!['admin', 'user', 'readonly'].includes(role)) {
    throw new Error('Invalid role');
  }
  const token: AuthToken = {
    userId: userId.replace(/[^a-zA-Z0-9_-]/g, ''),
    role,
    exp: Date.now() + TOKEN_EXPIRY_MS,
    nonce: crypto.randomBytes(16).toString('hex')
  };
  const payload = Buffer.from(JSON.stringify(token)).toString('base64url');
  const signature = generateSignature(payload);
  return `${payload}.${signature}`;
}

// Verify and decode an authentication token
export function verifyToken(token: string, clientIp: string): AuthToken | null {
  // Rate limiting check
  if (!checkRateLimit(clientIp)) {
    return null;
  }

  // Format validation
  if (!token || typeof token !== 'string' || !validateTokenFormat(token)) {
    recordFailedAttempt(clientIp);
    return null;
  }

  const [payload, signature] = token.split('.');

  // Verify HMAC signature
  if (!verifySignature(payload, signature)) {
    recordFailedAttempt(clientIp);
    return null;
  }

  // Decode and validate payload
  let decoded: AuthToken;
  try {
    decoded = JSON.parse(Buffer.from(payload, 'base64url').toString('utf-8'));
  } catch {
    recordFailedAttempt(clientIp);
    return null;
  }

  // Expiry check
  if (!decoded.exp || typeof decoded.exp !== 'number' || decoded.exp < Date.now()) {
    recordFailedAttempt(clientIp);
    return null;
  }

  // Validate role
  if (!['admin', 'user', 'readonly'].includes(decoded.role)) {
    recordFailedAttempt(clientIp);
    return null;
  }

  return decoded;
}

// Middleware for admin-only operations
export function requireAdmin(token: string, clientIp: string): boolean {
  const decoded = verifyToken(token, clientIp);
  if (!decoded) return false;
  return decoded.role === 'admin';
}

// API key verification for service-to-service auth
export function verifyApiKey(providedKey: string, storedKeyHash: string): boolean {
  if (!providedKey || typeof providedKey !== 'string') return false;
  if (providedKey.length < 32 || providedKey.length > 256) return false;

  const providedHash = crypto.createHash('sha256').update(providedKey).digest('hex');
  // Secure comparison of hex strings
  return providedHash === storedKeyHash;
}
